def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_reqs = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    total_req = WATER_REQ
    for r in opp_reqs:
        total_req += r

    scarcity_ratio = total_req / max(supply, 1.0)
    very_tight = supply <= WATER_REQ * 1.25
    tight = scarcity_ratio >= 2.2 or supply <= WATER_REQ * 1.6

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    critical = hp <= 2 or no_water_days >= 2
    urgent = hp <= 4 or no_water_days >= 1
    late_game = day >= 8

    if critical:
        target = max(DAILY_SALARY * 1.9, highest_prev + 4.0)
        if very_tight:
            target = max(target, DAILY_SALARY * 2.15)
        return float(min(budget, target))

    if urgent:
        if highest_prev >= 145:
            target = highest_prev + 2.5
        elif highest_prev >= 115:
            target = highest_prev + 3.0
        else:
            target = DAILY_SALARY * 1.45
        if very_tight:
            target += 6.0
        return float(min(budget, target))

    if tight:
        if highest_prev >= 140:
            target = highest_prev + 1.5
        elif highest_prev >= 110:
            target = highest_prev + 2.0
        else:
            target = max(DAILY_SALARY * 1.2, avg_prev + 8.0)
        if late_game:
            target += 3.0
        return float(min(budget, target))

    if highest_prev >= 145 and hp >= 5:
        return float(min(budget, DAILY_SALARY * 0.28))
    if highest_prev >= 120 and hp >= 6:
        return float(min(budget, DAILY_SALARY * 0.42))

    base = DAILY_SALARY * 0.58
    if late_game:
        base = DAILY_SALARY * 0.68
    if hp >= 8 and budget < DAILY_SALARY * 4:
        base = DAILY_SALARY * 0.45

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # Base bid: keep enough budget for future days.
    # If low HP or already in no-water streak, bid more.
    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.7
    elif hp <= 4.0:
        urgency += 0.4
    if no_water_days >= 2:
        urgency += 0.35
    if no_water_days >= 4:
        urgency += 0.35

    # Use yesterday's bids to infer aggressiveness.
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: higher supply means less competition; lower supply means more.
    # Normalize between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Target bid level.
    # If others were aggressive (high highest_prev_bid), lean upward but cap.
    aggressive_factor = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        aggressive_factor = 0.35
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        aggressive_factor = 0.2
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        aggressive_factor = 0.1

    # When supply is low, increase bid; when supply is high, decrease.
    scarcity_factor = (1.0 - supply_norm)  # 1 when supply is MIN, 0 when MAX

    # Compose final desired multiplier.
    desired_multiplier = 0.45 + aggressive_factor + urgency + 0.25 * scarcity_factor

    # If we are already in danger, push closer to salary.
    if urgency >= 0.7:
        desired_multiplier += 0.25

    # Convert to bid.
    bid = DAILY_SALARY * desired_multiplier

    # If yesterday bids were extremely high, add a small increment to beat them.
    if highest_prev_bid > 0.0:
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            bid = max(bid, highest_prev_bid * 0.9)
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            bid = max(bid, min(DAILY_SALARY, highest_prev_bid * 0.75))

    # Ensure we don't overspend; also avoid bidding too low.
    bid = max(0.0, bid)

    # Minimum bid to contest when alive opponents exist.
    if alive_opponents:
        min_contest = DAILY_SALARY * (0.25 + 0.25 * urgency + 0.15 * scarcity_factor)
    else:
        min_contest = DAILY_SALARY * 0.35

    bid = max(bid, min_contest)

    # Hard cap by budget.
    bid = min(bid, budget)

    # If budget is tiny, bid what's left.
    if bid <= 0.0 and budget > 0.0:
        bid = float(budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
